insert into fund_details(code,data) values ('KKP ACT FIXED-SSF', $J${"amc": "KKPAM", "cat": "Mid Term General Bond", "catTh": "ตราสารหนี้ระยะกลาง", "risk": 4, "div": "ไม่จ่าย", "mgmt": 1.605, "exp": 0.388, "front": 1, "back": 1, "inc": "2020-05-28", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนทั้งหมดหรือเกือบทั้งหมด", "strat": "กองทุนลงทุนในตราสารทั้งในประเทศและต่างประเทศ ในตราสารภาครัฐ รวมทั้งลงทุนในตราสารหนี้ที่ออกโดยธนาคารพาณิชย์หรือบริษัทเอกชน และ/หรือเงินฝาก และ/หรือหลักทรัพย์หรือทรัพย์สินอื่น หรือการหาดอกผลโดยวิธีอื่นอย่างหนึ่งอย่างใด หรือหลายอย่าง ตามที่คณะกรรมการ ก.ล.ต. หรือสำนักงานคณะกรรมการ ก.ล.ต. ประกาศกำหนด ทั้งนี้กองทุนจะนำเงินไปลงทุนในต่างประเทศไม่เกินร้อยละ 79 ของมูลค่าทรัพย์สินสุทธิของกองทุน", "r3m": 0.58372, "r6m": 0.91778, "r1y": 2.39502, "r3y": 2.87566, "na": 454168524.91, "top": [["พันธบัตรรัฐบาลประเภทอัตรา ดอกเบี้ยแปรผันตามการเปลี่ยน แปลงของเงินเฟ้อ (ILB283A)", 5.11], ["หุ้นกู้ของบริษัทบริหารสินทรัพย์ กรุงเทพพาณิชย์ จำกัด (มหาชน) (BAM284B)", 4.6], ["US TREASURY NOTE (US91282CNC19)", 4.56], ["TERM DEPOSIT QATAR NATIONAL BANK (QNB26521E)", 4.25], ["หุ้นกู้ของทรัสต์เพื่อการลงทุนใน อสังหาริมทรัพย์และสิทธิการเช่า ดับบลิวเอชเอ พรีเมี่ยม โกรท (WHART282A)", 3.47]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('KKP BL THAI ESGX-for LTF', $J${"amc": "KKPAM", "cat": "Aggressive Allocation", "catTh": "กองทุนรวมแบบผสมเชิงรุก (Aggressive)", "risk": 5, "div": "ไม่จ่าย", "mgmt": 2.675, "exp": 0, "front": 2, "back": 2, "inc": "2025-05-13", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนทั้งหมดหรือเกือบทั้งหมด", "strat": "กองทุนเป็นกองทุนผสมที่มีนโยบายการลงทุนในทรัพย์สินกลุ่มความยั่งยืน อย่างใดอย่างหนึ่งหรือหลายอย่างที่ออกโดยผู้ออกที่เป็นภาครัฐไทยหรือกิจการที่จัดตั้งขึ้นตามกฎหมายไทย ดังต่อไปนี้ ตามที่สำนักงาน ก.ล.ต. กำหนดหรือเห็นชอบให้กองทุนรวมไทยเพื่อความยั่งยืนแบบพิเศษ (Thailand ESG Extra Fund) สามารถลงทุนหรือมีไว้ได้ โดยมีการลงทุนและมี net exposure ในทรัพย์สินดังกล่าวโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุน หุ้นที่เป็นหลักทรัพย์จดทะเบียนใน SET บนกระดานหลัก ที่มีการเปิดเผยข้อมูลเกี่ยวกับการปล่อยก๊าซเรือนกระจก แผนการจัดการ และการตั้งเป้าหมายเพื่อให้บรรลุเป้าหมายในการลดปริมาณการปล่อยก๊าซเรือนกระจกของประเทศไทย รวมทั้งจัดให้มีการทวนสอบการจัดทำคาร์บอนฟุตพริ้นท์โดยผู้ทวนสอบที่สำนักงาน ก.ล.ต. ยอมรับ ทั้งนี้ สำนักงาน ก.ล.ต. อาจประกาศกำหนดแนวทางในการพิจารณาการเปิดเผยข้อมูลดังกล่าว โดยคำนึงถึงระดับการเปิดเผยข้อมูลหรือมาตรฐานสากลเกี่ยวกับการปล่อยก๊าซเรือนกระจกอันเป็นที่ยอมรับประกอบด้วยก็ได้ หุ้นที่เป็นหลักทรัพย์จดทะเบียนใน SET บนกระดานหลัก", "r3m": 6.0936, "r6m": 8.14097, "r1y": 22.23437, "r3y": null, "na": 768646778.01, "top": [["พันธบัตรรัฐบาลส่งเสริมความยั่งยืน (SLB406A)", 16.02], ["พันธบัตรรัฐบาล (ESGLB35DA)", 6.42], ["บริษัท ดับบลิวเอชเอ ยูทิลิตี้ส์ แอนด์ พาวเวอร์ จำกัด (มหาชน) (WHAUP)", 2.83], ["บริษัท ดับบลิวเอชเอ คอร์ปอเรชั่น จำกัด (มหาชน) (WHA)", 2.79], ["บริษัท อิออน ธนสินทรัพย์ (ไทยแลนด์) จำกัด (มหาชน) (AEONTS)", 2.75]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('KKP EQ THAI ESG', $J${"amc": "KKPAM", "cat": "Equity General", "catTh": "หุ้นไทยทั่วไป", "risk": 6, "div": "ไม่จ่าย", "mgmt": 2.675, "exp": 1.755, "front": 2, "back": 2, "inc": "2023-12-15", "feeder": "", "hedge": "", "strat": "เน้นลงทุนโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่า 80% ของ NAV ในหุ้นของบริษัทจดทะเบียนใน SET ที่มีความโดดเด่นด้านสิ่งแวดล้อม (Environment) หรือด้านความยั่งยืน (ESG) ทั้งนี้ กองทุนจะลงทุนในบริษัทที่มีผลการประเมิน ESG ที่ดีเป็นหลัก และพิจารณาลงทุนในบริษัทที่มีความสามารถในการปรับปรุงประเด็น ESG เพื่อให้ได้คะแนนการประเมินที่ดีขึ้นได้ โดยพอร์ตการลงทุนโดยรวมจะมีค่าเฉลี่ย SET ESG rating ในรอบปีบัญชีไม่ต่ำกว่า A ตามวิธีการคำนวณของ บลจ.", "r3m": 12.37282, "r6m": 18.18719, "r1y": 29.42771, "r3y": null, "na": 451887426.77, "top": [["ธนาคารเกียรตินาคินภัทร จำกัด (มหาชน) (KKP)", 7.05], ["บริษัท ปตท. จำกัด (มหาชน) (PTT)", 6.8], ["ธนาคารกสิกรไทย จำกัด (มหาชน) (KBANK)", 6.69], ["บริษัท ไทยประกันชีวิต จำกัด (มหาชน) (TLI)", 6.67], ["บริษัท กัลฟ์ ดีเวลลอปเมนท์ จำกัด (มหาชน) (GULF)", 6.66]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('KKP EWUS500-UH-SSF', $J${"amc": "KKPAM", "cat": "US Equity", "catTh": "หุ้นสหรัฐฯ", "risk": 6, "div": "ไม่จ่าย", "mgmt": 2.675, "exp": 1.214, "front": 2, "back": 2, "inc": "2024-12-23", "feeder": "Invesco S&P 500 Equal Weight ETF", "hedge": "ไม่ป้องกันความเสี่ยงอัตราแลกเปลี่ยน", "strat": "กองทุนเป็นกองทุนรวมหน่วยลงทุนประเภท Feeder Fund ที่เน้นลงทุนในหน่วยลงทุนของกองทุนรวมหลักในต่างประเทศเพียงกองทุนเดียว คือ Invesco S&P 500 Equal Weight ETF (“กองทุนหลัก”) ซึ่งจดทะเบียนซื้อขายในตลาดหลักทรัพย์ NYSE Arca ประเทศสหรัฐอเมริกา โดยกองทุนหลักมีวัตถุประสงค์ในการลงทุนเพื่อสร้างผลตอบแทน (ก่อนหักค่าธรรมเนียมและค่าใช้จ่าย) ให้สอดคล้องกับดัชนี S&P 500® Equal Weight Index (“ดัชนีอ้างอิง”) ประกอบไปด้วยหลักทรัพย์ที่เป็นองค์ประกอบทั้งหมดของดัชนี S&P 500® Index ซึ่งวัดผลการดำเนินงานของตราสารทุนของบริษัทขนาดใหญ่ในสหรัฐฯ โดยดัชนี S&P 500® Equal Weight Index มีรูปแบบการคำนวณด้วยวิธีถ่วงน้ำหนักเท่ากัน (equal weighting) กล่าวคือ คำนวณโดยให้แต่ละหลักทรัพย์ที่เป็นองค์ประกอบมีน้ำหนักที่เท่ากัน ทั้งนี้ กองทุนจะลงทุนในกองทุนหลักโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุนรวม โดยกองทุนมีนโยบายการลงทุนซึ่งส่งผลให้มี net exposure ที่เกี่ยวข้องกับความเสี่ยงต่างประเทศโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุน", "r3m": 7.39373, "r6m": 12.76845, "r1y": 17.89509, "r3y": null, "na": 2888262.12, "top": []}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
