insert into fund_details(code,data) values ('KKP SET50 ESG-SSF', $J${"amc": "KKPAM", "cat": "Equity Large Cap", "catTh": "หุ้นไทยขนาดใหญ่", "risk": 6, "div": "ไม่จ่าย", "mgmt": 1.605, "exp": 0.569, "front": 2, "back": 2, "inc": "2020-05-28", "feeder": "", "hedge": "", "strat": "กองทุนจะลงทุนในตราสารทุนโดยมี net exposure ในตราสารดังกล่าว โดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินของกองทุนรวม โดยกองทุนมีเป้าหมายมุ่งเน้นลงทุนในตราสารทุนของบริษัทจดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทยที่เป็นส่วนประกอบของดัชนี SET 50 โดยจะคัดเลือกหลักทรัพย์ตามหลักเกณฑ์ที่บริษัทจัดการกำหนด เช่น หลักเกณฑ์ด้านปัจจัยพื้นฐาน และ/หรือหลักเกณฑ์ที่เกี่ยวข้องกับการนโยบายและหรือการดำเนินการด้านสิ่งแวดล้อม สังคม และธรรมาภิบาล (Environmental, Social and Governance) เป็นต้น", "r3m": 8.79976, "r6m": 27.79965, "r1y": 50.92663, "r3y": 6.4711, "na": 265552095.89, "top": [["บริษัทเดลต้า อีเลคโทรนิคส์ (ประเทศไทย) จำกัด (มหาชน) (DELTA)", 11.62], ["บริษัท แอดวานซ์ อินโฟร์ เซอร์วิส จำกัด (มหาชน) (ADVANC)", 8.7], ["บริษัท ปตท. จำกัด (มหาชน) (PTT)", 8.67], ["บริษัท กัลฟ์ ดีเวลลอปเมนท์ จำกัด (มหาชน) (GULF)", 7.39], ["บริษัท ท่าอากาศยานไทย จำกัด (มหาชน) (AOT)", 6.29]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('KKP S-PLUS-SSF', $J${"amc": "KKPAM", "cat": "Short Term General Bond", "catTh": "ตราสารหนี้ระยะสั้น", "risk": 4, "div": "ไม่จ่าย", "mgmt": 1.605, "exp": 0.374, "front": 1, "back": 1, "inc": "2022-05-03", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนทั้งหมดหรือเกือบทั้งหมด", "strat": "กองทุนเป็นกองทุนตราสารหนี้ที่อาจพิจารณาลงทุนได้ทั้งตราสารหนี้ภาครัฐและหรือรัฐวิสาหกิจ และหรือเอกชน และหรือตราสารหนี้ที่เกี่ยวข้องกับธนาคารที่มีกฎหมายเฉพาะจัดตั้งขึ้น ตราสารหนี้ที่เกี่ยวข้องกับสถาบันการเงิน และหรือหน่วยลงทุนของกองทุนที่มีนโยบายที่กองทุนนี้สามารถลงทุนได้ และหรือเงินฝากและหรือตราสารเทียบเท่าเงินฝาก และหรือหลักทรัพย์หรือทรัพย์สินอื่นหรือการหาดอกผลโดยวิธีอื่นตามที่สำนักงานคณะกรรมการ ก.ล.ต.กำหนดหรืออนุญาต/เห็นชอบให้กองทุนลงทุนได้ โดยรวมกันไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุน กองทุนลงทุนอาจพิจารณาลงทุนได้ทั้งในประเทศและต่างประเทศ ทั้งนี้การพิจารณาลงทุนของกองทุนจะเป็นไปตามดุลพินิจของผู้จัดการกองทุน", "r3m": 0.38947, "r6m": 0.79969, "r1y": 1.90097, "r3y": 2.38789, "na": 37069406.05, "top": [["JAPAN TREASURY DISC BILL (JP1743421RB8)", 6.97], ["พันธบัตรธนาคารแห่งประเทศไทย (CB26507B)", 4.89], ["พันธบัตรธนาคารแห่งประเทศไทย (CBF26817A)", 4.13], ["JAPAN TREASURY DISC BILL (JP1743621S24)", 3.93], ["พันธบัตรธนาคารแห่งประเทศไทย (CBF26615A)", 3.73]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('KKP TECH-H-SSF', $J${"amc": "KKPAM", "cat": "Technology Equity", "catTh": "หุ้นกลุ่มเทคโนโลยี", "risk": 7, "div": "ไม่จ่าย", "mgmt": 2.675, "exp": 0.465, "front": 2, "back": 2, "inc": "2020-10-22", "feeder": "iShares Expanded Tech Sector ETF", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนทั้งหมดหรือเกือบทั้งหมด", "strat": "กองทุนเป็นกองทุนรวมหน่วยลงทุนประเภท Feeder Fund ที่เน้นลงทุนในหน่วยลงทุนของกองทุนรวมหลักในต่างประเทศเพียงกองทุนเดียว คือ iShares Expanded Tech Sector ETF (กองทุนหลัก) โดยลงทุนในสกุลเงินดอลลาร์สหรัฐ ซึ่งกองทุนหลักจดทะเบียนซื้อขายใน ตลาดหลักทรัพย์ NYSE Arca ประเทศสหรัฐอเมริกา เพียงตลาดหลักทรัพย์เดียว โดยกองทุนจะลงทุนในกองทุนหลักโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุนรวม เพื่อเป็นทางเลือกในการลงทุนระยะยาวของผู้ลงทุนที่ต้องการกระจายการลงทุนไปลงทุนในตราสารทุนของบริษัทในกลุ่มเทคโนโลยี รวมถึงตราสารทุนของบริษัทในกลุ่มบริการสื่อสาร (communication service) และกลุ่มสินค้าฟุ่มเฟือย (consumer discretionary) ในประเทศในทวีปอเมริกาเหนือ โดยกองทุนมีนโยบายการลงทุนซึ่งส่งผลให้มี net exposure ที่เกี่ยวข้องกับความเสี่ยงต่างประเทศโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุน", "r3m": 26.76771, "r6m": 24.90282, "r1y": 42.94984, "r3y": 30.63556, "na": 570191400.91, "top": [["ISHARES EXPANDED TECH SECTOR", 97.91], ["STANDARD CHARTERED BANK (THAI) PUBLIC CO.,LTD.", 0.98], ["BBL", 0.7], ["BBL", 0.24], ["KIATNAKIN PHATRA ASSET MANAGEMENT COMPANY LIMITED", 0.14]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
