insert into fund_details(code,data) values ('LHTHAIESG-A', $J${"amc": "LHFUND", "cat": "Equity General", "catTh": "หุ้นไทยทั่วไป", "risk": 6, "div": "ไม่จ่าย", "mgmt": 3.21, "exp": 0, "front": 2.5, "back": 2.5, "inc": "2023-12-21", "feeder": "", "hedge": "", "strat": "กองทุนมีนโยบายที่จะลงทุนในหุ้นที่เป็นหลักทรัพย์จดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย (“SET”) บนกระดานหลัก หรือกระดาน เอ็ม เอ ไอ (mai) ที่ได้รับการคัดเลือกจาก SET หรือองค์กรหรือสถาบันอื่นที่สำนักงาน ก.ล.ต.ยอมรับว่ามีความโดดเด่นด้านสิ่งแวดล้อม(Environment) หรือด้านความยั่งยืน (Environmental, Social and Governance: ESG) โดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ80ของมูลค่าทรัพย์สินสุทธิของกองทุน", "r3m": 5.62801, "r6m": 17.6573, "r1y": 38.74864, "r3y": null, "na": 14800652.72, "top": [["หุ้นสามัญ บริษัท กัลฟ์ เอ็นเนอร์จี ดีเวลลอปเมนท์ จำกัด (มหาชน)", 9.8687], ["หุ้นสามัญ บริษัท ปตท. จำกัด (มหาชน)", 9.4099], ["หุ้นสามัญ บริษัท เดลต้า อีเลคโทรนิคส์ (ประเทศไทย) จำกัด (มหาชน)", 8.9805], ["หุ้นสามัญ ธนาคาร กรุงไทย จำกัด (มหาชน)", 8.9188], ["หุ้นสามัญ ธนาคาร กสิกรไทย จำกัด (มหาชน)", 8.2812]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('LHTHAIESGX-LT', $J${"amc": "LHFUND", "cat": "Moderate Allocation", "catTh": "กองทุนรวมแบบผสมสมดุล (Moderate)", "risk": 5, "div": "ไม่จ่าย", "mgmt": 2, "exp": 0, "front": 2.5, "back": 2.5, "inc": "2025-05-09", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนทั้งหมดหรือเกือบทั้งหมด", "strat": "กองทุนมีนโยบายกระจายการลงทุนในหลักทรัพย์หรือทรัพย์สินอย่างใดอย่างหนึ่งหรือหลายอย่างที่ออกโดยผู้ออกที่เป็นภาครัฐไทยหรือกิจการที่จัดตั้งขึ้นตามกฎหมายไทยที่มีคุณสมบัติด้านความยั่งยืน ดังนี้ และมี net exposure ในทรัพย์สินที่ลงทุนดังกล่าวโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุน\nหุ้นที่เป็นหลักทรัพย์จดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย และ/หรือ ตลาดหลักทรัพย์ เอ็ม เอ ไอ ที่มีลักษณะดังนี้ โดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 65 ของมูลค่าทรัพย์สินสุทธิของกองทุนหุ้นที่เป็นหลักทรัพย์จดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย (SET) และ/หรือ ตลาดหลักทรัพย์ เอ็ม เอ ไอ (mai) หรือกระดาน mai ที่ได้รับการคัดเลือกจาก SET ว่ามีความโดดเด่นด้านสิ่งแวดล้อม (Environment) หรือด้านความยั่งยืน (Environmental, Social and Governance: ESG)", "r3m": 4.97275, "r6m": 15.59777, "r1y": 29.84508, "r3y": null, "na": 45455981.52, "top": [["หุ้นสามัญ บริษัท กัลฟ์ เอ็นเนอร์จี ดีเวลลอปเมนท์ จำกัด (มหาชน)", 10.0142], ["หุ้นสามัญ บริษัท ปตท. จำกัด (มหาชน)", 9.2539], ["หุ้นสามัญ ธนาคาร กรุงไทย จำกัด (มหาชน)", 9.2375], ["หุ้นสามัญ บริษัท แอดวานซ์ อินโฟร์ เซอร์วิส จำกัด (มหาชน)", 8.1902], ["หุ้นสามัญ บริษัท เดลต้า อีเลคโทรนิคส์ (ประเทศไทย) จำกัด (มหาชน)", 7.1225]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('LHUS-ASSF', $J${"amc": "LHFUND", "cat": "US Equity", "catTh": "หุ้นสหรัฐฯ", "risk": 6, "div": "ไม่จ่าย", "mgmt": 2.5, "exp": 0, "front": 2.5, "back": 2.5, "inc": "2024-02-28", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนตามดุลยพินิจของผู้จัดการกองทุนรวม", "strat": "กองทุนมีนโยบายที่จะลงทุนในหรือมีไว้ซึ่งหน่วยลงทุนของกองทุนรวมต่างประเทศ อาทิ หน่วย CIS และ/หรือ กองทุนรวมอีทีเอฟต่างประเทศที่มีนโยบายการลงทุนในตราสารทุน (กองทุนปลายทาง) โดยมี net exposure ในตราสารทุนโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุนรวม โดยจะลงทุนในกองทุนตั้งแต่ 2 กองทุนขึ้นไป โดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุนรวม ซึ่งกองทุนปลายทางดังกล่าวมีนโยบายเน้นลงทุนในตราสารทุนของบริษัทที่มีภูมิลำเนาและ/หรือ มีธุรกิจหลักอยู่ในประเทศสหรัฐอเมริกา และ/หรือ กองทุนปลายทางที่จดทะเบียนซื้อขายอยู่ในตลาดหลักทรัพย์ของประเทศสหรัฐอเมริกาที่อยู่ภายใต้การกำกับดูแลของทางการ (Regulated Markets)", "r3m": 8.18696, "r6m": -5.44917, "r1y": -6.44003, "r3y": null, "na": 455449.1, "top": [["หน่วยลงทุน State Street SPDR S&P Telecom ETF", 50.2257], ["หน่วยลงทุน Invesco S&P 500 Momentum ETF", 30.9616], ["หน่วยลงทุน Baillie Gifford Worldwide US Equity Growth Fund Class B USD Acc", 19.5139], ["บัญชีเงินฝากออมทรัพย์ ธนาคารกรุงไทย จำกัด (มหาชน)", 4.7534]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('LHUSFIN-ASSF', $J${"amc": "LHFUND", "cat": "Other Global Sector Equity", "catTh": "หุ้นทั่วโลก - กลุ่มอุตสาหกรรมอื่นๆ", "risk": 7, "div": "ไม่จ่าย", "mgmt": 2.5, "exp": 0, "front": 2.5, "back": 2.5, "inc": "2022-03-29", "feeder": "iShares U.S. Financial Services ETF", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนตามดุลยพินิจของผู้จัดการกองทุนรวม", "strat": "กองทุนมีนโยบายเน้นลงทุนในหน่วยลงทุนของกองทุนรวมต่างประเทศ (หรือ “กองทุนหลัก (Master fund)”) ที่มีนโยบายลงทุนในตราสารทุน และ/หรือหุ้นกลุ่มบริการทางการเงิน (Financial service) โดยจะลงทุนในกองทุนหลักเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิ ซึ่งกองทุนเปิด แอล เอช ยูเอส ไฟแนนเชียล จะลงทุนในหน่วยลงทุนของกองทุน iShares U.S. Financial Services ETF (“กองทุนหลัก”) สกุลเงินดอลล่าร์สหรัฐฯ (USD) ที่จดทะเบียนซื้อขายในตลาดหลักทรัพย์ NYSE Arca (New York Stock Exchange) ซึ่งกองทุนหลักได้จดทะเบียนจัดตั้งในประเทศสหรัฐอเมริกา (USA) บริหารและจัดการโดย BlackRock Fund Advisors (BFA)", "r3m": 9.28274, "r6m": -2.03539, "r1y": 6.88385, "r3y": 14.20084, "na": 1657498.17, "top": [["iShares U.S. Financial Service", 93.85], ["THE SIAM COMMERCIAL BANK PUBLIC COMPANY LIMITED", 6.36], ["KASIKORNBANK PUBLIC COMPANY LIMITED", 3.53], ["THE SIAM COMMERCIAL BANK PUBLIC COMPANY LIMITED", 2.61], ["KASIKORNBANK PUBLIC COMPANY LIMITED", 1.29]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('ONE-THAIESGX-L', $J${"amc": "ONEAM", "cat": "Equity General", "catTh": "หุ้นไทยทั่วไป", "risk": 6, "div": "ไม่จ่าย", "mgmt": 2.5, "exp": 0, "front": 2.14, "back": 2.14, "inc": "2025-05-09", "feeder": "", "hedge": "", "strat": "กองทุนมีนโยบายลงทุนเพื่อให้มี Net exposure ในหุ้นที่เป็นหลักทรัพย์จดทะเบียนใน SET บนกระดานหลัก หรือกระดาน mai ที่มีลักษณะอย่างใดอย่างหนึ่งหรือหลายอย่างดังนี้ \n1) ได้รับการคัดเลือกจากตลาดหลักทรัพย์แห่งประเทศไทยว่ามีความโดดเด่นด้านสิ่งแวดล้อม (Environment) หรือด้านความยั่งยืน (Environmental, Social and Governance: ESG) \n2) มีการเปิดเผยข้อมูลการปล่อยก๊าซเรือนกระจก แผนการจัดการ และการตั้งเป้าหมายเพื่อให้บรรลุเป้าหมายในการลดปริมาณการปล่อยก๊าซเรือนกระจกของประเทศไทย รวมทั้งจัดให้มีการทวนสอบการจัดทำคาร์บอนฟุตพริ้นท์โดยผู้ทวนสอบที่สำนักงาน ก.ล.ต. ยอมรับ \n3) มีบรรษัทภิบาล (governance: G) ในระดับดีเลิศ ซึ่งต้องได้รับ CGR ซึ่งจัดทำโดย IOD ตั้งแต่ 90 คะแนนเป็นต้นไป และมีการเปิดเผยเป้าหมายและแผนการเพิ่มมูลค่าบริษัท (corporate value up plan) และการยกระดับการดำเนินงานด้านสิ่งแวดล้อม และมีการรายงานความคืบหน้าการดำเนินการตามแผน.", "r3m": 7.72929, "r6m": 23.25549, "r1y": 39.86218, "r3y": null, "na": 165009467.86, "top": [["บริษัท ปตท. จำกัด (มหาชน)", 7.98], ["บริษัท แอดวานซ์ อินโฟร์ เซอร์วิส จำกัด (มหาชน)", 7.51], ["บริษัท กัลฟ์ ดีเวลลอปเมนท์ จำกัด (มหาชน)", 7.5], ["บริษัท เดลต้า อีเลคโทรนิคส์ (ประเทศไทย) จำกัด (มหาชน)", 7.44], ["บริษัท ปตท. สำรวจและผลิตปิโตรเลียม จำกัด (มหาชน)", 5.3]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('B-SI-THAIESG', $J${"amc": "BBLAM", "cat": "Long Term General Bond", "catTh": "ตราสารหนี้ระยะยาว", "risk": 3, "div": "ไม่จ่าย", "mgmt": 0.5885, "exp": 0.3, "front": 0, "back": 0, "inc": "2024-04-11", "feeder": "", "hedge": "", "strat": "กองทุนจะเน้นลงทุนในตราสารภาครัฐไทย อาทิ ตั๋วเงินคลัง พันธบัตรรัฐบาล พันธบัตรธนาคารแห่งประเทศไทย หรือพันธบัตรหรือตั๋วแลกเงินหรือตั๋วสัญญาใช้เงินหรือหุ้นกู้ที่กองทุนฟื้นฟูเป็นผู้ออก ผู้รับรอง ผู้รับอาวัล หรือผู้ค้ำประกัน หรือพันธบัตรหรือตั๋วแลกเงินหรือตั๋วสัญญาใช้เงินหรือหุ้นกู้ที่กระทรวงการคลังเป็นผู้ออก ผู้รับอาวัล หรือผู้ค้ำประกัน และ/หรือหลักทรัพย์หรือทรัพย์สินภาครัฐไทยอื่นใดตามที่สำนักงาน ก.ล.ต. อนุญาตให้กองทุนลงทุนได้ โดยเฉลี่ยรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุน ทั้งนี้ กองทุนจะลงทุนในพันธบัตรรัฐบาล พันธบัตรที่กระทรวงการคลังค้ำประกันต้นเงินและดอกเบี้ย หรือหุ้นกู้ที่กระทรวงการคลังค้ำประกันต้นเงินและดอกเบี้ยแต่ไม่รวมถึงหุ้นกู้แปลงสภาพ ซึ่งเป็นพันธบัตรหรือหุ้นกู้เพื่ออนุรักษ์สิ่งแวดล้อม (green bond) พันธบัตรหรือหุ้นกู้เพื่อความยั่งยืน (sustainability bond) หรือพันธบัตรหรือหุ้นกู้ส่งเสริมความยั่งยืน (sustainability – linked bond) โดยเฉลี่ยรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุน", "r3m": 0.61452, "r6m": -4.63481, "r1y": -4.71603, "r3y": null, "na": 6613635905.02, "top": [["พันธบัตรรัฐบาลส่งเสริมความยั่งยืน ในปีงบประมาณ พ.ศ. 2568 ครั้งที่ 1", 46.25], ["พันธบัตรรัฐบาลเพื่อความยั่งยืนสำหรับปรับโครงสร้างหนี้ (พ.ร.ก. กู้เงินโควิด-19) ในปีงบประมาณ พ.ศ. 256", 17.71], ["พันธบัตรรัฐบาลเพื่อการปรับโครงสร้างหนี้ (พ.ร.ก. กู้เงินโควิด-19) ในปีงบประมาณ พ.ศ. 2568 ครั้งที่ 2", 15.57], ["พันธบัตรเพื่อความยั่งยืน (Sustainability Bond) ในปีงบประมาณ พ.ศ. 2563", 8.81], ["พันธบัตรรัฐบาลเพื่อการบริหารหนี้ ในปีงบประมาณ พ.ศ. 2569 ครั้งที่ 9", 5.83]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('B-TOP-THAIESG', $J${"amc": "BBLAM", "cat": "Equity General", "catTh": "หุ้นไทยทั่วไป", "risk": 6, "div": "ไม่จ่าย", "mgmt": 2.14, "exp": 1.71, "front": 1, "back": 1, "inc": "2023-12-19", "feeder": "", "hedge": "", "strat": "กองทุนจะลงทุนในหุ้นของบริษัทจดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย (SET) และหรือตลาดหลักทรัพย์ เอ็ม เอ ไอ (mai) ที่ได้รับการคัดเลือกจาก SET หรือองค์กรหรือสถาบันอื่นที่สำนักงาน ก.ล.ต.ยอมรับว่ามีความโดดเด่นด้านสิ่งแวดล้อม (Environment) หรือด้านความยั่งยืน (Environmental Social and Governance: ESG) โดยผ่านกระบวนการวิเคราะห์การลงทุนแบบ ESG Integration ซึ่งผู้จัดการกองทุนคาดหมายว่าจะให้ผลตอบแทนรวมสูงสุด 10 อันดับแรก โดยเฉลี่ยรอบปีบัญชีไม่น้อยกว่า 80% ของมูลค่าทรัพย์สินสุทธิของกองทุน", "r3m": 5.49196, "r6m": 17.44023, "r1y": 31.32615, "r3y": null, "na": 2936775647.46, "top": [["หุ้นสามัญ ธนาคารกรุงไทย จำกัด (มหาชน)", 9.78], ["หุ้นสามัญ บริษัท กัลฟ์ ดีเวลลอปเมนท์ จำกัด (มหาชน)", 9.53], ["หุ้นสามัญ บริษัท ปตท. จำกัด (มหาชน)", 9.34], ["หุ้นสามัญ บริษัท ซีพี ออลล์ จำกัด (มหาชน)", 9.18], ["หุ้นสามัญ บริษัท ท่าอากาศยานไทย จำกัด (มหาชน)", 9.14]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('BM70-TESGX', $J${"amc": "BBLAM", "cat": "Aggressive Allocation", "catTh": "กองทุนรวมแบบผสมเชิงรุก (Aggressive)", "risk": 5, "div": "ไม่จ่าย", "mgmt": 1.605, "exp": 0, "front": 1, "back": 1, "inc": "2025-05-09", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนตามดุลยพินิจของผู้จัดการกองทุนรวม", "strat": "หุ้นที่เป็นหลักทรัพย์จดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย (SET) และ/หรือตลาด หลักทรัพย์ เอ็ม เอ ไอ (mai) โดยมี net exposure เฉลี่ยรอบปีบัญชีไม่น้อยกว่า 65% แต่ไม่เกิน 70% ของ มูลค่าทรัพย์สินสุทธิของกองทุน ที่มีลักษณะดังนี้ 1.1หุ้นของบริษัทจดทะเบียนที่ได้รับการ คัดเลือกจาก SET ว่ามีความโดดเด่นด้านสิ่งแวดล้อม (Environment) หรือด้านความยั่งยืน (ESG) และ/หรือ 1.2) หุ้นของบริษัทจดทะเบียนที่มีการเปิดเผยข้อมูลเกี่ยวกับการปล่อยก๊าซ เรือนกระจก แผนการจัดการ และการตั้งเป้าหมายเพื่อให้บรรลุเป้าหมายในการลดปริมาณ การปล่อยก๊าซเรือนกระจกของประเทศไทย และ/หรือ 1.3) หุ้นของบริษัทจดทะเบียนที่มีธรรมาภิบาล (Governance) ที่มีลักษณะเป็นไปตามประกาศ และ/หรือพันธบัตรรัฐบาล พันธบัตรหรือหุ้นกู้ที่กระทรวงการคลังค้ำประกันต้นเงินและดอกเบี้ยแต่ ไม่รวมถึงหุ้นกู้แปลงสภาพ ตราสารหนี้อื่นๆ โดยพันธบัตร หุ้นกู้หรือตราสารหนี้ต้องเป็น ตราสารเพื่ออนุรักษ์สิ่งแวดล้อม (green bond) เพื่อความยั่งยืน (sustainability bond) หรือ เพื่อส่งเสริมความยั่งยืน (sustainability - linked bond) ที่มีการเปิดเผยข้อมูลตามที่ สำนักงาน ก.ล.ต. กำหนด", "r3m": 6.86999, "r6m": 17.19291, "r1y": 28.09345, "r3y": null, "na": 3476785663.99, "top": [["หุ้นสามัญ บริษัท เดลต้า อีเลคโทรนิคส์ (ประเทศไทย) จำกัด (มหาชน)", 9.57], ["พันธบัตรรัฐบาลเพื่อความยั่งยืนสำหรับปรับโครงสร้างหนี้ (พ.ร.ก. กู้เงินโควิด-19)", 9.57], ["พันธบัตรเพื่อความยั่งยืน (Sustainability Bond) ในปีงบประมาณ พ.ศ. 2563", 6.46], ["หุ้นสามัญ บริษัท กัลฟ์ ดีเวลลอปเมนท์ จำกัด (มหาชน)", 6.17], ["พันธบัตรรัฐบาลส่งเสริมความยั่งยืน ในปีงบประมาณ พ.ศ. 2568 ครั้งที่ 1", 5.29]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
