insert into fund_details(code,data) values ('B-EQ-THAIESG', $J${"amc": "BBLAM", "cat": "Equity Large Cap", "catTh": "หุ้นไทยขนาดใหญ่", "risk": 6, "div": "ไม่จ่าย", "mgmt": 1.605, "exp": 1.76, "front": 1, "back": 1, "inc": "2024-11-01", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนตามดุลยพินิจของผู้จัดการกองทุนรวม", "strat": "กองทุนมีนโยบายลงทุนในหุ้นที่เป็นหลักทรัพย์จดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย (SET) และ/หรือตลาดหลักทรัพย์เอ็ม เอ ไอ (mai\nกองทุนมีสัดส่วนการลงทุนในต่างประเทศโดยเฉลี่ยรอบปีบัญชีไม่เกินร้อยละ 20 ของมูลค่าทรัพย์สินสุทธิของกองทุน ทั้งนี้ กองทุนจะป้องกันความเสี่ยงด้านอัตราแลกเปลี่ยนตามดุลยพินิจของผู้จัดการกองทุน", "r3m": 9.68717, "r6m": 25.27886, "r1y": 40.63125, "r3y": null, "na": 515238383.79, "top": [["หุ้นสามัญ บริษัทเดลต้า อีเลคโทรนิคส์ (ประเทศไทย) จำกัด (มหาชน)", 22.63], ["หุ้นสามัญ บริษัท กัลฟ์ ดีเวลลอปเมนท์ จำกัด (มหาชน)", 8.22], ["หุ้นสามัญ บริษัท ปตท. จำกัด (มหาชน)", 7.12], ["หุ้นสามัญ บริษัท แอดวานซ์ อินโฟร์ เซอร์วิส จำกัด (มหาชน)", 5.39], ["หุ้นสามัญ ธนาคารกสิกรไทย จำกัด (มหาชน)", 5.05]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
