insert into fund_details(code,data) values ('TCMF', $J${"amc": "UOBAM", "cat": "Money Market General", "catTh": "ตลาดเงินทั่วไป", "risk": 1, "div": "ไม่จ่าย", "mgmt": 0.5136, "exp": 0.127, "front": 0, "back": 0, "inc": "2000-12-08", "feeder": "", "hedge": "", "strat": "กองทุนรวมตลาดเงิน ที่ลงทุนในเงินฝาก ตราสารเทียบเท่าเงินฝาก พันธบัตรรัฐบาลหรือพันธบัตร ธปท. ซึ่งมีอายุไม่เกิน 397 วันโดยไม่มีความเสี่ยงต่างประเทศ ", "r3m": 0.21641, "r6m": 0.48047, "r1y": 1.16408, "r3y": 1.7025, "na": 24789488990.42, "top": [["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26611A 11/06/2026", 5.96], ["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26604A 04/06/2026", 4.83], ["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26730A 30/07/2026", 4.81], ["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26702B 02/07/2026", 4.25], ["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26528A 28/05/2026", 4.15]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('UOBSD', $J${"amc": "UOBAM", "cat": "Money Market Government", "catTh": "ตลาดเงินภาครัฐ", "risk": 1, "div": "ไม่จ่าย", "mgmt": 0.749, "exp": 0.1377, "front": 0.25, "back": 0.25, "inc": "2006-05-10", "feeder": "", "hedge": "", "strat": "ลงทุนในตราสารแห่งหนี้ภาครัฐ ได้แก่ ตั๋วเงินคลัง พันธบัตรรัฐบาล ตราสารแห่งหนี้ที่ออกโดยธนาคารแห่งประเทศไทย และรัฐวิสาหกิจที่กระทรวงการคลังเป็นผู้ออก ผู้รับรอง ผู้รับอาวัล หรือผู้ค้ำประกัน และเงินฝากธนาคาร ทั้งนี้ จะไม่ลงทุนในหรือมีไว้ซึ่งหลักทรัพย์หรือตราสารที่เสนอขายในต่างประเทศ ตราสารหนี้ที่มีการจ่ายผลตอบแทนอ้างอิงกับตัวแปร (Structured Notes) และสัญญาซื้อขายล่วงหน้า (Derivatives)", "r3m": 0.20281, "r6m": 0.4455, "r1y": 1.05889, "r3y": 1.60844, "na": 12511733609.1, "top": [["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26604A 04/06/2026", 18.39], ["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26618B 18/06/2026", 12.95], ["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26514A 14/05/2026", 11.81], ["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26709A 09/07/2026", 10.8], ["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26723A 23/07/2026", 8.68]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
