insert into fund_details(code,data) values ('UOBID', $J${"amc": "UOBAM", "cat": "Short Term General Bond", "catTh": "ตราสารหนี้ระยะสั้น", "risk": 4, "div": "ไม่จ่าย", "mgmt": 0.749, "exp": 0.3864, "front": 0.25, "back": 0.25, "inc": "2011-02-02", "feeder": "", "hedge": "", "strat": "\"กองทุนรวมนี้จะนำเงินไปลงทุนในทรัพย์ใด?\nกองทุนมีนโยบายเน้นลงทุนในตราสารภาครัฐ ตั๋วเงินคลัง พันธบัตรรัฐบาล พันธบัตรธนาคารแห่งประเทศไทย\nหรือพันธบัตร หรือตราสารหนี้ที่กองทุนเพื่อการฟื้นฟูและพัฒนาระบบสถาบันการเงินเป็น ผู้ออก ผู้รับรอง ผู้รับ\nอาวัล หรือผู้ค้ำประกัน หรือ พันธบัตรหรือตราสารแห่งหนี้ที่กระทรวงการคลังเป็น ผู้ออก ผู้รับอาวัล หรือผู้รับค้ำ\nประกัน นอกจากนั้นกองทุนสามารถลงทุนในตราสารหนี้ ตั๋วแลกเงิน และตั๋วสัญญาใช้เงินที่ออกโดยธนาคาร\nพาณิชย์ ธนาคารที่มีกฎหมายเฉพาะจัดตั้งขึ้น และสถาบันการเงิน ตราสารหนี้ภาคเอกชนที่ตัวตราสารหรือผู้ออก\nตราสารมีอันดับความน่าเชื่อถืออยู่ในอันดับที่สามารถลงทุนได้ (Investment Grade) รนี้ กองทุนจะไม่ลงทุนในสัญญาซื้อขายล่วงหน้า (Derivatives) ตราสารที่มีลักษณะของสัญญาซื้อขายล่วงหน้า\nแฝง (Structured Note) และตราสารหนี้ที่ไม่ได้รับการจัดอันดับความน่าเชื่อถือ (Unrated Securities)\"", "r3m": 0.17274, "r6m": 0.38307, "r1y": 0.95752, "r3y": 1.52497, "na": 1179929591.98, "top": [["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26618B 18/06/2026", 8.13], ["ตั๋วเงินคลัง : กระทรวงการคลัง อาวัลโดย กระทรวงการคลัง TB26506A 06/05/2026", 8.13], ["ตั๋วเงินคลัง : ธนาคารแห่งประเทศไทย CB26702B 02/07/2026", 8.12], ["ตั๋วแลกเงิน : ยริษัท ซีพี แอ็กซ์ตร้า จำกัด (มหาชน) CPAXT26O15A 15/10/2026", 6.47], ["ตั๋วแลกเงิน : บริษัท เอเซียเสริมกิจลีสซิ่ง จำกัด (มหาชน) ASK26514A 14/05/2026", 5.69]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('UIFT-SSF', $J${"amc": "UOBAM", "cat": "Foreign Investment Allocation", "catTh": "กองทุนรวมแบบผสมลงทุนต่างประเทศ", "risk": 5, "div": "ไม่จ่าย", "mgmt": 2.14, "exp": 1.3202, "front": 2, "back": 2, "inc": "2023-09-15", "feeder": "United CIO Income Fund - Class T USD Acc", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนทั้งหมดหรือเกือบทั้งหมด", "strat": "ลงทุนในกองทุน United Income Fund - Class T USD Acc\nกองทุนหลักจัดตั้งและบริหารจัดการโดย UOB Asset Management Ltd\nกองทุนหลักกระจายการลงทุนไปทั่วโลก อาจลงทุนทางอ้อมในบริษัทข้างต้นผ่านกองทุนรวม, กองทุนรวมอีทีเอฟ (ETFs) หรือ กองทรัสต์เพื่อการลงทุนในอสังหาริมทรัพย์ (REITs) และลงทุนโดยตรงในบริษัทผ่านตราสารทุน, หลักทรัพย์ที่เกี่ยวข้องกับตราสารทุน หรือ ตราสารหนี้ที่ออกโดยบริษัทเหล่านี้โดยตรง\nกองทุนอาจพิจารณาลงทุนใน Derivatives เพื่อเพิ่มประสิทธิภาพการบริหารการลงทุน\nมุ่งหวังให้ผลประกอบการเคลื่อนไหวตามกองทุนหลัก โดยกองทุนหลักใช้กลยุทธ์การบริหารกองทุนเชิงรุก (active management)", "r3m": 5.39476, "r6m": 5.69071, "r1y": 12.48298, "r3y": null, "na": 22299514.24, "top": [["หน่วยลงทุน : United CIO Income Fund - Class T USD Acc", 101.78], ["อื่นๆ", -1.78]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('UOBSHC-SSF', $J${"amc": "UOBAM", "cat": "Health Care", "catTh": "หุ้นกลุ่มอุตสาหกรรมการดูแลสุขภาพ", "risk": 7, "div": "ไม่จ่าย", "mgmt": 2.14, "exp": 1.8568, "front": 2, "back": 0, "inc": "2020-11-03", "feeder": "United Global Healthcare Fund", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนตามดุลยพินิจของผู้จัดการกองทุนรวม", "strat": "ลงทุนในกองทุนหลัก United Global Healthcare Fund ซึ่งจดทะเบียนในสิงคโปร์ ไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิ กองทุนหลักมีนโยบายเน้นการลงทุนส่วนใหญ่ในหุ้นของบริษัทในกลุ่ม Health Care", "r3m": 0.2442, "r6m": -3.0472, "r1y": 13.11459, "r3y": -1.95575, "na": 141097849.22, "top": [["หน่วยลงทุน : United Global Healthcare Fund - Class SGD Acc (Ref.USD)", 102.27], ["อื่นๆ", -2.27]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('UPOP-SSF', $J${"amc": "UOBAM", "cat": "Foreign Investment Allocation", "catTh": "กองทุนรวมแบบผสมลงทุนต่างประเทศ", "risk": 5, "div": "ไม่จ่าย", "mgmt": 2.14, "exp": 0, "front": 2, "back": 2, "inc": "2020-04-23", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนตามดุลยพินิจของผู้จัดการกองทุนรวม", "strat": "กองทุนจะเน้นลงทุนในหน่วยลงทุนของกองทุน CIS กองทุน Infra กองทุน property กองทุน Private equity หรือ กองทุนอีทีเอฟ (ETF) (กองทุนปลายทาง) ตั้งแต่ 2 กองทุนขึ้นไป โดยจะมี net exposure ที่เกี่ยวข้องกับความเสี่ยงต่างประเทศโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุน ทั้งนี้กองทุนปลายทางอาจมีนโยบายลงทุนหรือมีไว้ซึ่งทรัพย์สินอย่างใดอย่างหนึ่งหรือหลายอย่าง ดังนี้ ตราสารทุน ตราสารหนี้ โครงสร้างพื้นฐาน อสังหาริมทรัพย์ ทรัพย์สินทางเลือก เช่น ทองคำ และ/หรือน้ำมันดิบ และ/หรือสินค้าโภคภัณฑ์ และ/หรือหลักทรัพย์หรือทรัพย์สินอื่นใดตามที่กฎหมาย ก.ล.ต. กำหนด นอกจากนี้กองทุนปลายทางอาจลงทุนหรือมีไวซึ้่งตราสารหนี้ที่มีอันดับความน่าเชื่อถือตํ่ากว่าที่สามารถลงทุนได้ (Non-investment grade) ตราสารหนี้ที่ไม่ไดรั้บการจัดอันดับความน่าเชื่อถือ (Unrated) และตราสารทุนที่ไม่ได้จดทะเบียนในตลาดหลักทรัพย์ (Unlisted securities) โดยขึ้นอยู่กับนโยบายการลงทุนของกองทุนปลายทางนั้นๆทั้งนี้ กองทุนจะลงทุนในกองทุนปลายทางโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุน", "r3m": 5.37406, "r6m": 8.18796, "r1y": 14.88, "r3y": 6.20191, "na": 15356700.11, "top": [["หน่วยลงทุน : iShares MSCI ACWI ETF", 31.23], ["หน่วยลงทุน : PIMCO GIS Income Fund (Class I)", 20.68], ["หน่วยลงทุน : United SGD Fund A (Acc) USD (Hedged)", 15.33], ["หน่วยลงทุน : Invesco S&P 500 Equal Weight ETF", 7.66], ["หน่วยลงทุน : iShares MSCI All Country Asia ex Japan ETF", 3.46]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
