insert into fund_details(code,data) values ('UMIX-TESGX-N68L', $J${"amc": "UOBAM", "cat": "Moderate Allocation", "catTh": "กองทุนรวมแบบผสมสมดุล (Moderate)", "risk": 5, "div": "ไม่จ่าย", "mgmt": 2.675, "exp": 0, "front": 3, "back": 2, "inc": "2025-05-09", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนตามดุลยพินิจของผู้จัดการกองทุนรวม", "strat": "\"ลงทุนในหลักทรัพย์หรือทรัพย์สินดังต่อไปนี้ โดยมี net exposure โดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่า 80% ของ NAV\nหุ้นที่เป็นหลักทรัพย์จดทะเบียนใน SET บนกระดานหลัก และ/หรือ mai ที่มีลักษณะดังนี้\nบริษัทที่มีการดำเนินธุรกิจที่ได้รับการคัดเลือกจาก SET ว่ามีความโดดเด่นด้าน Environmental หรือ ESG ซึ่งประกอบไปด้วยปัจจัยด้าน Environmental, Social และ Governance\nบริษัทที่มีการเปิดเผยข้อมูลเกี่ยวกับการปล่อยก๊าซเรือนกระจก\nบริษัทที่มีการยกระดับด้าน Governance\nอนึ่ง กองทุนจะลงทุนในหรือมีไว้ซึ่งตราสารทุน โดยมี net exposure โดยเฉลี่ยในรอบปีบัญชีไม่เกิน 70% ของ NAV โดย net exposure ในหุ้นกลุ่มยั่งยืน ตามข้อ (1) โดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่า 65% ของ NAV (2) ตราสารอย่างใดอย่างหนึ่ง หรือหลายอย่างดังนี้\nตราสารเพื่ออนุรักษ์สิ่งแวดล้อม ตราสารเพื่อความยั่งยืน หรือตราสารส่งเสริมความยั่งยืน\nพันธบัตรรัฐบาล พันธบัตรที่กระทรวงการคลังคํ้าประกันต้นเงินและดอกเบี้ย ฯลฯ\"", "r3m": 4.92224, "r6m": 10.27285, "r1y": 19.63304, "r3y": null, "na": 821993894.22, "top": [["พันธบัตร : กระทรวงการคลัง ESGLB376A 17/06/20 3.390", 30.73], ["หุ้นสามัญ : บริษัท ปตท. สำรวจและผลิตปิโตรเลียม จำกัด (มหาชน)", 5.48], ["หุ้นสามัญ : บริษัท กัลฟ์ ดีเวลลอปเมนท์ จำกัด (มหาชน)", 5.32], ["หุ้นสามัญ : บริษัท แอดวานซ์ อินโฟร์ เซอร์วิส จำกัด (มหาชน)", 4.43], ["หุ้นสามัญ : บริษัท ท่าอากาศยานไทย จำกัด (มหาชน)", 4.14]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('UTSEQ-THAIESG', $J${"amc": "UOBAM", "cat": "Equity General", "catTh": "หุ้นไทยทั่วไป", "risk": 6, "div": "ไม่จ่าย", "mgmt": 2.675, "exp": 1.8451, "front": 3, "back": 2, "inc": "2023-12-19", "feeder": "", "hedge": "", "strat": "ลงทุนในหุ้นของบริษัทจดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย และ/หรือตลาดหลักทรัพย์ เอ็ม เอ ไอ โดยเน้นลงทุนในบริษัทที่มีการดำเนินธุรกิจที่ได้รับการคัดเลือกจากตลาดหลักทรัพย์แห่งประเทศไทย หรือองค์กร หรือสถาบันอื่นที่สำนักงานยอมรับว่ามีความโดดเด่นด้านสิ่งแวดล้อม (Environmental) หรือด้านความยั่งยืน (ESG) ซึ่งประกอบไปด้วยปัจจัยด้านสิ่งแวดล้อม (Environmental) สังคม (Social) และการกำกับดูแลกิจการที่ดี (Governance) โดยกองทุนจะลงทุนในหุ้นดังกล่าวโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของ Nav", "r3m": 7.69053, "r6m": 16.7076, "r1y": 25.53907, "r3y": null, "na": 702865240.74, "top": [["บริษัท กัลฟ์ ดีเวลลอปเมนท์ จำกัด (มหาชน)", 8.55], ["ธนาคาร กสิกรไทย จำกัด (มหาชน)", 6.54], ["บริษัท แอดวานซ์ อินโฟร์ เซอร์วิส จำกัด (มหาชน)", 6.31], ["บริษัท ปตท. สำรวจและผลิตปิโตรเลียม จำกัด (มหาชน)", 6.21], ["บริษัท ปตท. จำกัด (มหาชน)", 5.47]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('SCBTB(ThaiESGA)', $J${"amc": "SCBAM", "cat": "Long Term General Bond", "catTh": "ตราสารหนี้ระยะยาว", "risk": 4, "div": "ไม่จ่าย", "mgmt": 1.07, "exp": 0.4, "front": 3.21, "back": 3.21, "inc": "2024-09-17", "feeder": "", "hedge": "", "strat": "กองทุนมีนโยบายการลงทุนในตราสารเพื่ออนุรักษ์สิ่งแวดล้อม (green bond) ตราสารเพื่อความยั่งยืน (sustainability bond) หรือตราสารส่งเสริมความยั่งยืน (sustainability - linked bond) ที่มีการเปิดเผยข้อมูลตามที่สำนักงานคณะกรรมการ ก.ล.ต. กำหนด หรือพันธบัตรหรือหุ้นกู้เพื่ออนุรักษ์สิ่งแวดล้อม (green bond) พันธบัตรหรือหุ้นกู้เพื่อความยั่งยืน (sustainability bond) หรือพันธบัตรหรือหุ้นกู้ส่งเสริมความยั่งยืน (sustainability - linked bond) โดยมี net exposure ในทรัพย์สินดังกล่าวโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุนรวม", "r3m": 0.3609, "r6m": -4.44432, "r1y": -4.91924, "r3y": null, "na": 4741274337, "top": [["พันธบัตรรัฐบาล ส่งเสริมความยั่งยืน ในปีงบประมาณ พ.ศ. 2568 ครั้งที่ 1", 34.1], ["พันธบัตรรัฐบาลเพื่อความยั่งยืนสำหรับปรับโครงสร้างหนี้ (พ.ร.ก. กู้เงินโควิด-19) ในปีงบประมาณ พ.ศ. 2565 ครั้งที่ 5", 28.58], ["พันธบัตรรัฐบาลเพื่อความยั่งยืนสำหรับบริหารหนี้ให้กู้ต่อในปีงบประมาณ พ.ศ. 2563 ครั้งที่ 1", 18.93], ["พันธบัตรรัฐบาลในปีงบประมาณ พ.ศ. 2569 ครั้งที่ 11", 3.97], ["หุ้นกู้ส่งเสริมความยั่งยืนของบริษัท โรงแรมเซ็นทรัลพลาซา จำกัด (มหาชน) ครั้งที่ 3/2568", 3.06]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('SCBT70X(LTFA)', $J${"amc": "SCBAM", "cat": "Aggressive Allocation", "catTh": "กองทุนรวมแบบผสมเชิงรุก (Aggressive)", "risk": 5, "div": "ไม่จ่าย", "mgmt": 2.14, "exp": 0, "front": 3.21, "back": 3.21, "inc": "2025-05-13", "feeder": "", "hedge": "", "strat": "กองทุนจะลงทุนในหุ้นของบริษัทจดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทยบนกระดานหลักและ/หรือตลาดหลักทรัพย์เอ็มเอ ไอ โดยจะเน้นลงทุนในบริษัทที่มีความโดดเด่นในการบริหารจัดการด้านสิ่งแวดล้อม (Environment) หรือด้านความยั่งยืน (Environmental, Social and Governance: ESG) และ/หรือบริษัทที่ช่วยลดผลกระทบของการเปลี่ยนแปลงของสภาพภูมิอากาศ ซึ่งมีแผนการจัดการ และการตั้งเป้าหมายเพื่อให้บรรลุเป้าหมายในการลดปริมาณการปล่อยก๊าซเรือนกระจกของประเทศไทย และ/หรือบริษัทจดทะเบียนที่มีธรรมาภิบาล (Governance) และจะลงทุนในตราสารหนี้เพื่ออนุรักษ์สิ่งแวดล้อม (green bond) ตราสารหนี้เพื่อความยั่งยืน (sustainability bond) หรือตราสารหนี้ส่งเสริมความยั่งยืน (sustainability - linked bond) ซึ่งผ่านกระบวนการวิเคราะห์การลงทุนแบบ ESG Integration โดยมี net exposure ในทรัพย์สินดังกล่าว โดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุนรวม", "r3m": 6.84074, "r6m": 18.04272, "r1y": 30.13293, "r3y": null, "na": 815684746, "top": [["พันธบัตรรัฐบาลเพื่อความยั่งยืนสำหรับปรับโครงสร้างหนี้ (พ.ร.ก. กู้เงินโควิด-19) ในปีงบประมาณ พ.ศ. 2565 ครั้งที่ 5", 18.24], ["หุ้น บมจ.เดลต้า อีเลคโทรนิคส์ (ประเทศไทย)", 14.66], ["พันธบัตรรัฐบาล ส่งเสริมความยั่งยืน ในปีงบประมาณ พ.ศ. 2568 ครั้งที่ 1", 5.39], ["หุ้น บมจ.กัลฟ์ ดีเวลลอปเมนท์", 4.98], ["พันธบัตรธนาคารแห่งประเทศไทยงวดที่ 14/91/69", 4.39]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('SCBTM(ThaiESGA)', $J${"amc": "SCBAM", "cat": "Aggressive Allocation", "catTh": "กองทุนรวมแบบผสมเชิงรุก (Aggressive)", "risk": 5, "div": "ไม่จ่าย", "mgmt": 1.61, "exp": 1.68, "front": 3.21, "back": 3.21, "inc": "2023-12-18", "feeder": "", "hedge": "", "strat": "กองทุนจะลงทุนในหุ้นที่เป็นส่วนประกอบของดัชนี SET ESG Total Return Index ซึ่งเป็นหลักทรัพย์ที่จดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย และ/หรือตลาดหลักทรัพย์ เอ็ม เอ ไอ ที่มีความโดดเด่นในการบริหารจัดการด้านสิ่งแวดล้อม สังคม และธรรมาภิบาล (Environmental, Social and Governance: ESG) เพื่อสร้างผลตอบแทนที่ยั่งยืนให้กับผู้ถือหน่วยลงทุน โดยกองทุนมี net exposure ในตราสารดังกล่าวโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุนรวม", "r3m": 4.9545, "r6m": 14.79749, "r1y": 33.83234, "r3y": null, "na": 1099445432.33, "top": [["เงินฝากออมทรัพย์ บมจ.ธนาคารยูโอบี", 7.89], ["หุ้น บมจ.แอดวานซ์ อินโฟร์ เซอร์วิส", 6.98], ["หุ้น บมจ.กัลฟ์ ดีเวลลอปเมนท์", 6.69], ["หุ้น บมจ.เซ็นทรัลพัฒนา", 5.99], ["หุ้น บมจ.ท่าอากาศยานไทย", 5.73]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
