insert into fund_details(code,data) values ('ES-DIV70THAIESGX-LA', $J${"amc": "EASTSPRING", "cat": "Equity Large Cap", "catTh": "หุ้นไทยขนาดใหญ่", "risk": 5, "div": "ไม่จ่าย", "mgmt": 1.605, "exp": 0, "front": 1, "back": 1, "inc": "2025-05-19", "feeder": "", "hedge": "", "strat": "กองทุนมีนโยบายกระจายการลงทุนในหรือมีไว้ซึ่งหลักทรัพย์หรือทรัพย์สินดังต่อไปนี้ ที่ออกโดยผู้ออกที่เป็นตราสารภาครัฐไทยหรือกิจการที่จัดตั้งขึ้นตามกฎหมายไทย ทั้งนี้ กองทุนจะมี net exposure ในหลักทรัพย์หรือทรัพย์สินดังกล่าวรวมกัน ดังนี้ โดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุนหุ้นที่เป็นหลักทรัพย์จดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย (SET) บนกระดานหลัก หรือกระดานเอ็มเอไอ (mai) ที่มีประวัติการจ่ายปันผลดี สม่ำเสมอ หรือมีแนวโน้มจ่ายเงินปันผลดีในอนาคต และได้รับการคัดเลือกจาก SET ว่ามีความโดดเด่นด้านสิ่งแวดล้อม (Environment) หรือด้านความยั่งยืน (Environmental, Social and Governance: ESG) โดยผ่านการคัดเลือกและได้รับการประกาศผลประเมินหุ้นยั่งยืน SET ESG Ratings ของ SET ในระดับตั้งแต่ AA ขึ้นไป", "r3m": 4.93899, "r6m": 8.82452, "r1y": 21.09397, "r3y": null, "na": 397280627.92, "top": [["พันธบัตรรัฐบาลเพื่อความยั่งยืนสำหรับปรับโครงสร้างหนี้ (พ.ร.ก. กู้เงินโควิด-19)", 16.43], ["ธนาคารกสิกรไทย จำกัด (มหาชน)", 7.65], ["บริษัท ปตท. จำกัด (มหาชน)", 7.4], ["ธนาคารกรุงเทพ จำกัด (มหาชน)", 6.68], ["พันธบัตรรัฐบาลส่งเสริมความยั่งยืน ในปีงบประมาณ พ.ศ. 2568 ครั้งที่ 1", 6.68]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
