insert into fund_details(code,data) values ('ES-CASH', $J${"amc": "EASTSPRING", "cat": "Money Market General", "catTh": "ตลาดเงินทั่วไป", "risk": 1, "div": "ไม่จ่าย", "mgmt": 0.321, "exp": 0.343, "front": 0, "back": 0, "inc": "2005-08-31", "feeder": "", "hedge": "", "strat": "กองทุนจะลงทุนในเงินฝาก ตราสารแห่งหนี้ ธุรกรรมทางการเงิน หรือตราสารทางการเงินอื่นใด ที่มีกำหนดชำระคืนเมื่อทวงถามหรือจะครบกำหนดชำระคืนหรือมีอายุสัญญาไม่เกิน 1 ปี นับแต่วันที่ลงทุน รวมถึงตราสารทางการเงิน หลักทรัพย์ หรือการหาดอกผล ด้วยวิธีอื่น กองทุนอาจลงทุนในสัญญาซื้อขายล่วงหน้าเพื่อป้องกันความเสี่ยงที่เกี่ยวข้องกับการลงทุน ทั้งนี้ จะไม่ลงทุนในสัญญาซื้อขายล่วงหน้า เพื่อแสวงหาผลประโยชน์ตอบแทนและตราสารหนี้ที่มีการจ่ายผลตอบแทนอ้างอิงกับตัวแปร", "r3m": 0.20292, "r6m": 0.41152, "r1y": 1.05382, "r3y": 1.72396, "na": 18527383899, "top": [["พันธบัตร : พันธบัตรธนาคารแห่งประเทศไทย (CB26917A)", 7.64], ["พันธบัตร : พันธบัตรธนาคารแห่งประเทศไทย (CB26709A)", 5.84], ["พันธบัตร : พันธบัตรธนาคารแห่งประเทศไทย (CB26604A)", 5.56], ["ตั๋วแลกเงิน : บริษัท บางจาก ศรีราชา จำกัด (มหาชน) (BSRC26806B)", 5.35], ["ตั๋วแลกเงิน : บริษัท เซ็นทรัลพัฒนา จำกัด (มหาชน) (CPN26O01A)", 5.35]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('ES-SETESG-ThaiESG-A', $J${"amc": "EASTSPRING", "cat": "Equity Large Cap", "catTh": "หุ้นไทยขนาดใหญ่", "risk": 6, "div": "ไม่จ่าย", "mgmt": 1.605, "exp": 0, "front": 1.5, "back": 0, "inc": "2023-12-20", "feeder": "", "hedge": "", "strat": "กองทุนมีนโยบายที่จะเน้นลงทุนในหุ้นที่เป็นองค์ประกอบของดัชนีผลตอบแทนรวม SETESG Index (SETESG TRI) เพื่อสร้างผลตอบแทนให้ใกล้เคียงกับดัชนีดังกล่าว โดยจะลงทุนโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินของกองทุน\nทั้งนี้ กองทุนจะใช้กลยุทธ์การบริหารกองทุนเชิงรับ (Passive management strategy) โดยจะเลือกลงทุนเฉพาะในหุ้นที่เป็นหลักทรัพย์จดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย (“SET”) บนกระดานหลัก หรือกระดานเอ็มเอไอ (mai) ที่ได้รับการคัดเลือกจาก SET หรือองค์กรหรือสถาบันอื่นที่ สำนักงาน ก.ล.ต. ยอมรับว่ามีความโดดเด่นด้านความยั่งยืน (Environmental Social and Governance: ESG) ในสัดส่วนที่เท่าหรือใกล้เคียงกับน้ำหนักที่เป็นส่วนประกอบของดัชนีดังกล่าว โดยจะพยายามดำรงค่าความผันผวนของส่วนต่างของผลตอบแทนเฉลี่ยของกองทุนรวมและผลตอบแทนของดัชนีชี้วัด (tracking error : “TE” ไม่เกิน 1.00% ต่อปี)", "r3m": 9.1321, "r6m": 20.33482, "r1y": 39.15882, "r3y": null, "na": 529178056.11, "top": [["บริษัท กัลฟ์ เอ็นเนอร์จี ดีเวลลอปเมนท์ จำกัด (มหาชน)", 5.14], ["บริษัท ท่าอากาศยานไทย จำกัด (มหาชน)", 5.1], ["บริษัท ปตท. จำกัด (มหาชน)", 5.07], ["ธนาคารกสิกรไทย จำกัด (มหาชน)", 4.99], ["ธนาคารกรุงไทย จำกัด (มหาชน)", 4.79]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('ES-ESG3070-ThaiESG-A', $J${"amc": "EASTSPRING", "cat": "Conservative Allocation", "catTh": "กองทุนรวมแบบผสมเสี่ยงต่ำ (Conservative)", "risk": 5, "div": "ไม่จ่าย", "mgmt": 1.605, "exp": 0.5846, "front": 1, "back": 1, "inc": "2024-10-31", "feeder": "", "hedge": "", "strat": "1. นโยบายการลงทุน ส่วนที่ 1 กองทุนมีนโยบายกระจายการลงทุนในหรือมีไว้ซึ่งหลักทรัพย์หรือทรัพย์สินดังต่อไปนี้ ที่ออกโดยผู้ออกที่เป็นตราสารภาครัฐไทยหรือกิจการที่จัดตั้งขึ้นตามกฎหมายไทย และมี net exposure ในทรัพย์สินส่วนที่ 1 โดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่าร้อยละ 80 ของมูลค่าทรัพย์สินสุทธิของกองทุน\n1.1 หุ้นที่เป็นองค์ประกอบของดัชนีผลตอบแทนรวม SETESG Index (SETESG TRI) กองทุนจะลงทุนในหุ้นที่เป็นหลักทรัพย์จดทะเบียนในตลาดหลักทรัพย์แห่งประเทศไทย (SET) บนกระดานหลัก หรือกระดานเอ็มเอไอ (mai) ที่ได้รับการคัดเลือกจาก SET ว่ามีความโดดเด่นด้านสิ่งแวดล้อม (Environment) หรือด้านความยั่งยืน (Environmental Social and Governance: ESG)\n1.2 ตราสารอย่างใดอย่างหนึ่ง หรือหลายอย่าง", "r3m": 2.86066, "r6m": 2.87155, "r1y": 6.67731, "r3y": null, "na": 605975491.02, "top": [["พันธบัตรรัฐบาลส่งเสริมความยั่งยืน ในปีงบประมาณ พ.ศ. 2568 ครั้งที่ 1", 26.35], ["พันธบัตรรัฐบาลเพื่อความยั่งยืนสำหรับปรับโครงสร้างหนี้ (พ.ร.ก. กู้เงินโควิด-19)", 12.05], ["พันธบัตรรัฐบาลเพื่อความยั่งยืนสำหรับบริหารหนี้ให้กู้ต่อในปีงบประมาณ พ.ศ. 2563 ครั้งที่ 1", 8.09], ["พันธบัตรธนาคารแห่งประเทศไทยงวดที่ 9/364/68", 4.64], ["หุ้นกู้เพื่อความยั่งยืนของบริษัท ทางด่วนและรถไฟฟ้ากรุงเทพ จำกัด (มหาชน)", 3.91]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('K-CHANGE-SSF', $J${"amc": "KASSET", "cat": "Global Equity", "catTh": "หุ้นทั่วโลก", "risk": 6, "div": "ไม่จ่าย", "mgmt": 3.21, "exp": 0, "front": 3, "back": 3, "inc": "2020-05-11", "feeder": "Baillie Gifford Positive Change Fund", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนบางส่วน", "strat": "กองทุนหุ้นต่างประเทศที่บริหารโดย Baillie Gifford Asset Management ผ่านกองทุน Baillie Gifford Positive Change Fund​​ ที่มีนโยบายลงทุนในหุ้นของบริษัททั่วโลกซึ่งเป็นเจ้าของผลิตภัณฑ์หรือมีพฤติกรรมที่ส่งผลกระทบเชิงบวก (Positive Impact) ต่อสังคมโดยรวม หรือสนับสนุนให้เกิดการเปลี่ยนแปลงในด้านต่างๆ เช่น การศึกษา ความเท่าเทียมทางสังคม คุณภาพของระบบการดูแลสุขภาพ และด้านทรัพยากรและสิ่งแวดล้อม เป็นต้น", "r3m": 10.08951, "r6m": 6.75318, "r1y": 9.23515, "r3y": 2.69716, "na": 4905482366.15, "top": [["Baillie Gifford Positive Change Fund", 100.89], ["เงินฝาก บมจ.ธนาคารทหารไทยธนชาต", 2.28], ["เงินฝาก บมจ.ธนาคารกสิกรไทย", 0.09]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('K-CHINA-A(D)', $J${"amc": "KASSET", "cat": "Greater China Equity", "catTh": "หุ้นจีน", "risk": 6, "div": "จ่าย", "mgmt": 2.675, "exp": 0.57, "front": 1.5, "back": 1.5, "inc": "2009-11-04", "feeder": "JPMorgan Funds – China Fund, Class JPM China I (acc) – USD", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนบางส่วน", "strat": "กองทุนรวมหุ้นต่างประเทศที่ี่เน้นลงทุนในบริษัทที่มีการตั้งถิ่นฐานหรือดำเนินธุรกิจในจีน ผ่านกองทุนหลัก  JPMorgan Funds – China Fund โดยคัดเลือกธุรกิจที่จะลงทุนแบบ bottom-up stock และเลือกลงทุนในธุรกิจที่มีศักยภาพในการเติบโตที่เหนือกว่าคู่แข่งอย่างยั่งยืน โดยเฉพาะอย่างยิ่งหุ้นกลุ่มเศรษฐกิจใหม่ (New Economy) ที่ได้ประโยชน์จากแผนพัฒนาเศรษฐกิจจากรัฐบาลจีน", "r3m": -2.66921, "r6m": -2.94462, "r1y": 8.2661, "r3y": -1.08494, "na": 11170747048.06, "top": [["JPM China I (acc) - USD", 100.44], ["เงินฝาก บมจ.ธนาคารกรุงเทพ", 2.25], ["เงินฝาก บมจ.ธนาคารกสิกรไทย", 0.18]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('K-TNZ-ThaiESG', $J${"amc": "KASSET", "cat": "Equity Large Cap", "catTh": "หุ้นไทยขนาดใหญ่", "risk": 6, "div": "ไม่จ่าย", "mgmt": 1.07, "exp": 0, "front": 1, "back": 1, "inc": "2023-12-22", "feeder": "", "hedge": "", "strat": "กองทุนมีวัตถุประสงค์ในการช่วยส่งเสริมการลดผลกระทบจากการเปลี่ยนแปลงของสภาพภูมิอากาศ และมีการบริหารจัดการพอร์ตการลงทุนโดยมีเป้าหมายให้ปริมาณการปล่อยก๊าซเรือนกระจกโดยเฉลี่ยถ่วงน้ำหนักรวมและอุณหภูมิของพอร์ตการลงทุนรวมต่ำกว่าดัชนีชี้วัด และสนับสนุนให้ภาคธุรกิจมีส่วนในการขับเคลื่อนประเทศไทยให้สามารถบรรลุเป้าหมายตามข้อตกลงปารีสที่มุ่งลดการปล่อยก๊าซเรือนกระจกเป็นศูนย์ (Net Zero) ภายในปี พ.ศ. 2608", "r3m": 9.16211, "r6m": 27.72425, "r1y": 50.7527, "r3y": null, "na": 5778656425.92, "top": [["หุ้น บมจ.เดลต้า อีเลคโทรนิคส์(ประเทศไทย)", 10.94], ["หุ้น บมจ.ปตท.", 7.53], ["หุ้น บมจ.แอดวานซ์ อินโฟร์ เซอร์วิส", 7.43], ["หุ้น บมจ. กัลฟ์ ดีเวลลอปเมนท์", 6.41], ["หุ้น บมจ.ท่าอากาศยานไทย", 5.29]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('K-ESGSI-ThaiESG', $J${"amc": "KASSET", "cat": "Long Term General Bond", "catTh": "ตราสารหนี้ระยะยาว", "risk": 3, "div": "ไม่จ่าย", "mgmt": 1.07, "exp": 0, "front": 1, "back": 1, "inc": "2024-07-03", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนทั้งหมดหรือเกือบทั้งหมด", "strat": "กองทุนจะลงทุนในพันธบัตรรัฐบาล พันธบัตรที่กระทรวงการคลังคํ้าประกันต้นเงินและดอกเบี้ย หรือหุ้นกู้ที่กระทรวงการคลังค้ำประกันต้นเงินและดอกเบี้ยแต่ไม่รวมถึงหุ้นกู้แปลงสภาพ ซึ่งเป็นพันธบัตรหรือหุ้นกู้เพื่ออนุรักษ์สิ่งแวดล้อม (green bond) พันธบัตรหรือหุ้นกู้เพื่อความยั่งยืน (sustainability bond) หรือพันธบัตรหรือหุ้นกู้ส่งเสริมความยั่งยืน (sustainability – linked bond) โดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่า 80% ของ NAV", "r3m": 0.28916, "r6m": -4.35804, "r1y": -5.08434, "r3y": null, "na": 10000731108.47, "top": [["พันธบัตร (ESGLB376A)", 40.42], ["พันธบัตร (SLB406A)", 31.72], ["พันธบัตร (ESGLB35DA)", 21.52], ["พันธบัตร (LB456A)", 1.78], ["พันธบัตร (CBF26O12A)", 1.34]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
insert into fund_details(code,data) values ('K-70ThaiESGX-L', $J${"amc": "KASSET", "cat": "Aggressive Allocation", "catTh": "กองทุนรวมแบบผสมเชิงรุก (Aggressive)", "risk": 5, "div": "จ่าย", "mgmt": 3.21, "exp": 0, "front": 1, "back": 1, "inc": "2025-05-14", "feeder": "", "hedge": "ป้องกันความเสี่ยงอัตราแลกเปลี่ยนทั้งหมดหรือเกือบทั้งหมด", "strat": "กองทุนจะลงทุนใน (1) หุ้นที่มีความโดดเด่นด้านสิ่งแวดล้อม (Environment) หรือด้านความยั่งยืน (ESG) และหรือหุ้นที่มีการเปิดเผยข้อมูล แผนการจัดการ และการตั้งเป้าหมายเพื่อให้บรรลุเป้าหมายในการลดปริมาณการปล่อยก๊าซเรือนกระจก และหรือหุ้นที่มีธรรมาภิบาล (Governance) และ (2) ตราสารเพื่ออนุรักษ์สิ่งแวดล้อม (green bond) และหรือตราสารเพื่อความยั่งยืน (sustainability bond) และหรือตราสารส่งเสริมความยั่งยืน (sustainability – linked bond) โดยมี net exposure ในทรัพย์สินดังกล่าวรวมกันโดยเฉลี่ยในรอบปีบัญชีไม่น้อยกว่า 80% ของมูลค่าทรัพย์สินสุทธิ", "r3m": 6.6599, "r6m": 13.65991, "r1y": 26.80231, "r3y": null, "na": 4529315965.53, "top": [["หุ้น บมจ.ธนาคารกสิกรไทย", 7.76], ["หุ้น บมจ.ปตท.", 6.58], ["หุ้น บมจ.เอสซีบี เอกซ์", 6.56], ["หุ้น บมจ.ธนาคารกรุงไทย", 6.42], ["หุ้น บมจ.ธนาคารกรุงเทพ", 6.3]]}$J$::jsonb) on conflict (code) do update set data=excluded.data, updated_at=now();
